#!/bin/sh
# GTK fonts & rendering via XSETTINGS (xsettingsd), scoped to $DISPLAY.

gtk_font="${gtk_font:-Inter 10}"
xsettings_conf="$MIRA_DIR/config/xsettingsd.conf"

_write "$xsettings_conf" << EOF
# Generated by Theme.sh (theme: ${THEME}).
Gtk/FontName "${gtk_font}"
Xft/Antialias 1
Xft/Hinting 1
Xft/HintStyle "hintslight"
Xft/RGBA "rgb"
Xft/DPI 98304
EOF

if command -v xsettingsd >/dev/null 2>&1; then
    cur_disp="${DISPLAY:-:0}"
    reloaded=0
    for p in $(pgrep -u "$(id -u)" -x xsettingsd 2>/dev/null); do
        d=$(tr '\0' '\n' <"/proc/$p/environ" 2>/dev/null | sed -n 's/^DISPLAY=//p' | head -n 1)
        [ "$d" = "$cur_disp" ] || continue
        if tr '\0' ' ' <"/proc/$p/cmdline" 2>/dev/null | grep -Fq "$xsettings_conf"; then
            kill -HUP "$p" 2>/dev/null && reloaded=1
        else
            kill "$p" 2>/dev/null || true
        fi
    done
    [ "$reloaded" -eq 1 ] || xsettingsd -c "$xsettings_conf" >/dev/null 2>&1 &
fi
